416	                + "VALUES ('x', 1, 0, CURRENT_TIMESTAMP(6))");
417	        assertThatThrownBy(() -> jdbcTemplate.update(
418	                "INSERT INTO artifact (name, version, withdrawn, created_at) "
419	                        + "VALUES ('x', 1, 0, CURRENT_TIMESTAMP(6))"))
420	                .isInstanceOf(org.springframework.dao.DuplicateKeyException.class);
421	    }
