423	    @Test
424	    void withdrawnArtifactVersionRemainsAndBlocksReRegistration() {
425	        service.registerArtifact(requestId(), artifact("app", 1));
426	        service.withdrawArtifact(requestId(), "app", 1);
427	
428	        Integer withdrawnFlag = jdbcTemplate.queryForObject(
429	                "SELECT withdrawn FROM artifact WHERE name = 'app' AND version = 1",
430	                Integer.class);
431	        assertThat(withdrawnFlag).isEqualTo(1);
432	
433	        // 撤回不删除：同 name+version 仍视为已存在，重新登记 409。
434	        assertThatThrownBy(() -> service.registerArtifact(requestId(), artifact("app", 1)))
435	                .isInstanceOfSatisfying(ApiException.class,
436	                        e -> assertThat(e.getStatus()).isEqualTo(409));
437	    }
