439	    @Test
440	    void lockReplayAfterUnrelatedChangesStillReturnsOriginalResolution() {
441	        service.registerArtifact(requestId(), artifact("app", 1, dep("lib", 1, 2)));
442	        service.registerArtifact(requestId(), artifact("lib", 1));
443	        String rid = requestId();
444	        LockFileResponse first = service.createLock(rid, new LockRequest("app", 1, 2L));
445	
446	        // 登记 lib2 并撤回 lib1，仓库前进。
447	        service.registerArtifact(requestId(), artifact("lib", 2));
448	        service.withdrawArtifact(requestId(), "lib", 1);
449	
450	        LockFileResponse replay = service.createLock(rid, new LockRequest("app", 1, 2L));
451	        assertThat(replay.id()).isEqualTo(first.id());
452	        assertThat(replay.repositoryVersion()).isEqualTo(2L);
453	        assertThat(replay.entries()).isEqualTo(first.entries());
454	    }
455	}
