        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(1) FROM release_snapshot_item", Integer.class)).isZero();
        assertThat(jdbcTemplate.queryForObject(
                "SELECT COUNT(1) FROM release_snapshot_entry", Integer.class)).isZero();
